import{_ as t,o as a,c as o,a3 as i}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"ioBroker Blockly","description":"Introduction to Blockly in the ioBroker JavaScript adapter with an official starter example.","frontmatter":{"title":"ioBroker Blockly","description":"Introduction to Blockly in the ioBroker JavaScript adapter with an official starter example."},"headers":[],"relativePath":"en/blog/snippets/iobroker-blockly.md","filePath":"en/blog/snippets/iobroker-blockly.md","lastUpdated":1792861636000}'),r={name:"en/blog/snippets/iobroker-blockly.md"};function l(s,e,n,c,p,h){return a(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="iobroker-blockly" tabindex="-1">ioBroker Blockly <a class="header-anchor" href="#iobroker-blockly" aria-label="Permalink to &quot;ioBroker Blockly&quot;">​</a></h1><p>Blockly is the graphical script editor of the <strong>ioBroker JavaScript adapter</strong>. Automations are built from blocks without having to write all JavaScript code by hand.</p><div class="info custom-block"><p class="custom-block-title">Official documentation</p><p>This page only gives a short introduction. The complete description of all blocks and more examples are available in the official ioBroker documentation.</p></div><h2 id="official-sources" tabindex="-1">Official Sources <a class="header-anchor" href="#official-sources" aria-label="Permalink to &quot;Official Sources&quot;">​</a></h2><ul><li><a href="https://github.com/ioBroker/ioBroker.javascript" target="_blank" rel="noreferrer">ioBroker.javascript - official repository</a></li><li><a href="https://github.com/ioBroker/ioBroker.javascript/tree/master/docs/de" target="_blank" rel="noreferrer">German JavaScript adapter documentation</a></li><li><a href="https://github.com/ioBroker/ioBroker.javascript/blob/master/docs/de/blockly.md" target="_blank" rel="noreferrer">Complete Blockly documentation</a></li></ul><h2 id="example-1-switch-a-data-point-based-on-another-data-point" tabindex="-1">Example 1: Switch a Data Point Based on Another Data Point <a class="header-anchor" href="#example-1-switch-a-data-point-based-on-another-data-point" aria-label="Permalink to &quot;Example 1: Switch a Data Point Based on Another Data Point&quot;">​</a></h2><p>The official starter example shows a typical motion detection workflow:</p><ul><li>A motion data point is used as the trigger.</li><li>On a state change, a light data point is controlled.</li><li>The current value of the motion detector is passed to the light data point.</li><li>Motion turns the light on.</li><li>No motion turns the light off again.</li></ul><p><a href="https://github.com/ioBroker/ioBroker.javascript/blob/master/docs/de/blockly.md#beispiel-1" target="_blank" rel="noreferrer"><img src="https://raw.githubusercontent.com/ioBroker/ioBroker.javascript/master/docs/de/img/getting_started_1_de.png" alt="Official ioBroker Blockly example 1"></a></p><small> Image source and rights note: The image comes from the official <a href="https://github.com/ioBroker/ioBroker.javascript" target="_blank" rel="noopener">ioBroker.javascript repository</a>. Rights and license terms follow the project and license published there. </small><h2 id="required-blockly-blocks" tabindex="-1">Required Blockly Blocks <a class="header-anchor" href="#required-blockly-blocks" aria-label="Permalink to &quot;Required Blockly Blocks&quot;">​</a></h2><h3 id="_1-trigger" tabindex="-1">1. Trigger <a class="header-anchor" href="#_1-trigger" aria-label="Permalink to &quot;1. Trigger&quot;">​</a></h3><p>Use the <strong>If object</strong> block from the <strong>Trigger</strong> section.</p><p>Select the motion detector data point there.</p><h3 id="_2-control-data-point" tabindex="-1">2. Control Data Point <a class="header-anchor" href="#_2-control-data-point" aria-label="Permalink to &quot;2. Control Data Point&quot;">​</a></h3><p>Insert the <strong>Control</strong> block from the <strong>System</strong> section.</p><p>Select the light data point as the target.</p><h3 id="_3-use-the-current-value" tabindex="-1">3. Use the Current Value <a class="header-anchor" href="#_3-use-the-current-value" aria-label="Permalink to &quot;3. Use the Current Value&quot;">​</a></h3><p>Insert <strong>Value of object ID</strong> into the control block.</p><p>Select the motion data point again. The light then uses the current true/false state of the motion detector.</p><h2 id="simplified-flow" tabindex="-1">Simplified Flow <a class="header-anchor" href="#simplified-flow" aria-label="Permalink to &quot;Simplified Flow&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>When the motion detector changes</span></span>
<span class="line"><span>    set the state of the light</span></span>
<span class="line"><span>    to the current value of the motion detector</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="import-blockly" tabindex="-1">Import Blockly <a class="header-anchor" href="#import-blockly" aria-label="Permalink to &quot;Import Blockly&quot;">​</a></h2><p>The official documentation provides the full importable XML code directly under <strong>Example 1</strong>:</p><p><a href="https://github.com/ioBroker/ioBroker.javascript/blob/master/docs/de/blockly.md#beispiel-1" target="_blank" rel="noreferrer">Open example 1 with Blockly XML</a></p><p>Copy the XML code there and paste it into the Blockly editor through the import function.</p><h2 id="more-official-examples" tabindex="-1">More Official Examples <a class="header-anchor" href="#more-official-examples" aria-label="Permalink to &quot;More Official Examples&quot;">​</a></h2><p>The official documentation also contains:</p><ul><li><strong>Example 2:</strong> Turn on a light on motion and turn it off again after ten minutes without further motion.</li><li><strong>Example 3:</strong> Send an email when the outside temperature exceeds a threshold.</li></ul><p><a href="https://github.com/ioBroker/ioBroker.javascript/blob/master/docs/de/blockly.md#getting-started" target="_blank" rel="noreferrer">View all official Blockly examples</a></p><h2 id="own-blockly-posts-in-the-blog" tabindex="-1">Own Blockly Posts in the Blog <a class="header-anchor" href="#own-blockly-posts-in-the-blog" aria-label="Permalink to &quot;Own Blockly Posts in the Blog&quot;">​</a></h2><p>For custom examples, this structure is recommended:</p><ol><li>describe the task</li><li>list required object IDs</li><li>add a screenshot of the Blockly structure</li><li>provide exported Blockly XML code</li><li>explain adjustments and requirements</li></ol><p>Screenshots are stored in the documentation project here:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docs/public/images/blog/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Embedding in a post:</p><div class="language-md vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">![</span><span style="--shiki-light:#032F62;--shiki-light-text-decoration:underline;--shiki-dark:#DBEDFF;--shiki-dark-text-decoration:underline;">ioBroker Blockly</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">](</span><span style="--shiki-light:#24292E;--shiki-light-text-decoration:underline;--shiki-dark:#E1E4E8;--shiki-dark-text-decoration:underline;">/images/blog/my-blockly.png</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Object IDs from examples must always be adapted to your own ioBroker system.</p></div>`,38)])])}const u=t(r,[["render",l]]);export{m as __pageData,u as default};
